<script setup lang="ts">
import { computed, watch, watchEffect } from 'vue'
import { useDemoStore } from '../../stores/demo'
import AppBreadcrumb from '../../components/layout/AppBreadcrumb.vue'
import PageHeader from '../../components/common/PageHeader.vue'
import EmptyState from '../../components/common/EmptyState.vue'
const store=useDemoStore(), s=store.state
const docs=computed(()=>s.docs.filter(d=>s.chunks.some(c=>c.docId===d.id)))
watchEffect(()=>{ if (!docs.value.some(d=>d.id===s.vecCfg.docId) && docs.value.length) s.vecCfg.docId=docs.value[0].id })
const chunks=computed(()=>s.chunks.filter(c=>c.docId===s.vecCfg.docId)), done=computed(()=>chunks.value.filter(c=>c.vectorized).length)
const complete=computed(()=>done.value===chunks.value.length && done.value>0)
const pct=computed(()=>s.vectorBusy || s.vectorStep===3 ? s.vectorProgress : complete.value ? 100 : 0)
const coverage=computed(()=>s.docs.filter(d=>s.chunks.some(c=>c.docId===d.id && c.vectorized)).length)
const steps=['读取已保存的文本块','调用 Embedding 模型生成向量','写入向量库并建立索引']
watch(()=>s.vecCfg.docId,()=>{ if (!s.vectorBusy) { s.vectorStep=-1;s.vectorProgress=0;s.vectorSub='';s.vecLog=[] } })
</script>
<template><div class="page"><AppBreadcrumb/><PageHeader title="向量入库" subtitle="调用 Embedding 模型把文本块转成向量，写入向量库供检索使用。"><span class="badge green live">向量库正常</span></PageHeader><div v-if="docs.length" class="split-2"><div class="card cfg-card"><div class="field"><label for="vecDoc">选择文档</label><select id="vecDoc" v-model="s.vecCfg.docId" class="select" :disabled="s.vectorBusy"><option v-for="d in docs" :key="d.id" :value="d.id">{{ d.name }}（{{ s.chunks.filter(c=>c.docId===d.id).length }} 段）</option></select></div><div class="field"><label for="vecModel">Embedding 模型</label><select id="vecModel" v-model="s.vecCfg.model" class="select" :disabled="s.vectorBusy"><option>bge-large-zh-v1.5</option><option>bge-m3</option><option>text-embedding-3-large</option></select><div class="hint">演示环境使用前端哈希向量（384 维），生产环境由后端模型服务生成。</div></div><div class="field"><label for="vecBatch">批次大小</label><select id="vecBatch" v-model.number="s.vecCfg.batch" class="select" :disabled="s.vectorBusy"><option v-for="n in [8,16,32]" :key="n" :value="n">{{ n }} 条 / 批</option></select></div><div class="hint-box"><AppIcon name="info" :size="14"/><div>入库前请确认切块结果已保存。重新切块会使已有向量失效，需要重新入库。</div></div><button class="btn primary block lg" :disabled="s.vectorBusy || !chunks.length" @click="store.vectorize"><AppIcon :name="s.vectorBusy?'refresh':'database'" :size="15"/> {{ s.vectorBusy?'正在处理…':complete?'重新向量化':'开始向量入库' }}</button><div class="hint" style="text-align:center;margin-top:8px">当前文档已入库 {{ done }} / {{ chunks.length }} 段</div></div><div><div id="runPanel" class="card run-panel"><div class="run-head"><b>入库进度</b><span class="badge" :class="{green:complete&&!s.vectorBusy}">{{ s.vectorBusy?'处理中':complete?'已完成':'待执行' }}</span></div><div id="runPct" class="run-big">{{ pct }}<small>%</small></div><div id="runSub" class="run-sub">{{ s.vectorSub || (complete?'全部文本块已写入向量库':'点击左侧按钮开始处理') }}</div><div class="progress-line" style="margin:14px 0 18px" role="progressbar" :aria-valuenow="pct" aria-valuemin="0" aria-valuemax="100" aria-label="向量入库进度"><i id="runBar" :style="{width:pct+'%'}"></i></div><div id="runSteps" class="run-steps"><div v-for="(step,i) in steps" :key="step" class="run-step" :class="{done:s.vectorBusy?s.vectorStep>i:complete,active:s.vectorBusy&&s.vectorStep===i}"><span class="step-dot"><AppIcon name="check" :size="10"/></span>{{ step }}</div></div><div id="runLog" class="run-log" aria-live="polite"><template v-if="s.vecLog.length">{{ s.vecLog.join('\n') }}</template><template v-else><span class="t">[系统]</span> 向量库就绪 · 集合 <span class="ok">yyt_knowledge</span> · 现有 {{ store.vectorCount }} 条向量</template></div></div><div class="card collection" style="padding:16px 18px"><div class="card-head" style="padding:0 0 8px;border:0"><b>向量索引概览</b><span class="sub">yyt_knowledge</span></div><div class="coll-row"><span>向量总数</span><b>{{ store.vectorCount }} 条</b></div><div class="coll-row"><span>向量维度</span><b>384 维</b></div><div class="coll-row"><span>索引类型</span><b>FAISS FlatIP（余弦）</b></div><div class="coll-row"><span>覆盖文档</span><b>{{ coverage }} 份</b></div></div></div></div><div v-else class="card"><EmptyState icon="database" title="还没有可入库的文本块" description="请先在「文本切块」中保存文档的切块结果"/><div style="text-align:center;padding-bottom:30px"><RouterLink class="btn primary" to="/chunk">去切块</RouterLink></div></div></div></template>
